{"task_id": "T04", "code": "def solve(s):
    """Return True if brackets in s are balanced.
    Supports (), [], {}. Ignores other characters.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack
