def solve(tokens):
    """Evaluate an expression given in Reverse Polish Notation.
    Supports the operators +, -, *, /. Division truncates toward zero as
    required by the problem statement.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Python's // floors toward -inf; we need truncation toward zero.
                # Use int(a / b) which truncates toward zero for ints.
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

