def solve(grid):
    """Count number of islands (4-directionally connected 1s) in a binary grid.
    Args:
        grid (list[list[int]]): 2D list containing 0s and 1s.
    Returns:
        int: Number of distinct islands.
    """
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and grid[ni][nj]==1:
                    stack.append((ni,nj))
    islands = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j]==1 and not visited[i][j]:
                islands += 1
                dfs(i,j)
    return islands

